mapper.select:
SELECT DATE_FORMAT(CONVERT_TZ(e.created_at, '+00:00', #{offset}), '%Y-%m-%d') AS bucket,
       COUNT(*) AS amount
FROM exec_records e
WHERE e.user_id = #{userId}
  AND e.created_at >= #{from}
GROUP BY bucket

SELECT e.session_id AS bucket, COUNT(*) AS amount
FROM exec_records e
WHERE e.user_id = #{userId}
  AND e.created_at >= #{from}
GROUP BY e.session_id
